komponenten-inputs-forms-checkbox--inter.snippet:
import { Component } from '@angular/core';
import { CheckboxComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [CheckboxComponent],
  template: `
    <cds-checkbox
        [label]="'Ich bin einverstanden, dass meine E-Mail-Adresse für den Versand des Newsletters verwendet wird.'"
        [linkLabel]="'Datenschutzhinweise'"
        [linkHref]="'#'"
        [required]="true"
        [checked]="false"
        [disabled]="false"
        [area]="'co'"
        (checkedChange)="checkedChange($event)"
        (disabledChange)="disabledChange($event)"
    />`,
})
export class DemoComponent {
  checkedChange(event: unknown) {}
  disabledChange(event: unknown) {}
}

